/**
 * Dual-channel emitter: prefers Node.js native IPC channel (`stdio[3] = 'ipc'`) when connected,
 * with automatic fallback to stdout/stderr markers for one-shot mode and unit tests.
 */
function sendIpc(event, fallbackFn) {
  if (typeof process.send === 'function' && process.connected) {
    try {
      process.send({ __aiartEvent: true, ...event })
      return true
    } catch {
      /* fallback to stdio markers */
    }
  }
  if (typeof fallbackFn === 'function') fallbackFn()
  return false
}

const SUMMARY_KEYS = [
  'path',
  'pattern',
  'query',
  'name',
  'title',
  'description',
  'prompt',
  'command',
  'url',
  'file',
  'dir',
  'relativePath'
]

function summarizeToolArgs(raw) {
  if (typeof raw !== 'string' || raw === '') return ''
  try {
    const parsed = JSON.parse(raw)
    for (const key of SUMMARY_KEYS) {
      const value = parsed[key]
      if (typeof value === 'string' && value !== '')
        return value.length > 80 ? value.slice(0, 80) + '…' : value
    }
    const candidates = Object.values(parsed)
      .filter((v) => typeof v === 'string' && v !== '')
      .sort((a, b) => a.length - b.length)
    if (candidates.length) {
      const value = candidates[0]
      return value.length > 80 ? value.slice(0, 80) + '…' : value
    }
    const json = JSON.stringify(parsed)
    if (json === '{}' || json === '[]') return ''
    return json.length > 80 ? json.slice(0, 80) + '…' : json
  } catch {
    return raw.length > 80 ? raw.slice(0, 80) + '…' : raw
  }
}

function clipToolArgs(raw) {
  if (raw === undefined || raw === null || raw === '') return ''
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw)
  if (typeof text !== 'string' || text === '') return ''
  return text.length > 4000 ? text.slice(0, 4000) + '…' : text
}

function extractToolResultSteps(eventData) {
  try {
    const content = eventData?.message?.content
    if (!Array.isArray(content)) return undefined
    for (const block of content) {
      if (!block || block.type !== 'text' || typeof block.text !== 'string') continue
      const text = block.text.trim()
      if (!text.startsWith('{')) continue
      const parsed = JSON.parse(text)
      const obj =
        parsed && typeof parsed.result === 'object' && parsed.result !== null
          ? parsed.result
          : parsed
      if (obj && Array.isArray(obj.applied) && obj.applied.length > 0) {
        const steps = obj.applied
          .filter((item) => typeof item === 'string' && item.trim() !== '')
          .map((item) => item.trim())
        if (steps.length > 0) return steps
      }
    }
  } catch {
    /* ignore */
  }
  return undefined
}

const GEMINI_CHAT_FALLBACK_MODELS = [
  'gemini-3.8-flash',
  'gemini-3.6-flash',
  'gemini-3.5-flash',
  'gemini-flash-latest',
  'gemini-3-flash-preview'
]

const OPENAI_CHAT_FALLBACK_MODELS = [
  'gpt-6.1-terra',
  'gpt-6-sol',
  'gpt-5.5',
  'gpt-5.4',
  'gpt-4.1',
  'gpt-4o'
]

const OPENAI_CHAT_MODEL_ALIASES = {
  'gpt-6.1': 'gpt-6.1-sol',
  'gpt-6.1-pro': 'gpt-6.1-sol',
  'gpt-6.1-mini': 'gpt-6.1-terra',
  'gpt-6.1-nano': 'gpt-6.1-terra',
  'gpt-6': 'gpt-6-astra',
  'gpt-6-pro': 'gpt-6-astra',
  'gpt-6-mini': 'gpt-6-luna',
  'gpt-5.6': 'gpt-5.6-sol',
  'gpt-5.6-pro': 'gpt-5.6-sol',
  'gpt-5.6-mini': 'gpt-5.6-terra'
}

const OPENAI_CHAT_TOOLS_MODEL_MAP = {
  'gpt-6.1-sol': 'gpt-6.1-terra',
  'gpt-6-astra': 'gpt-6-sol'
}

function isOpenAiEndpoint(urlStr, modelId) {
  if (typeof urlStr === 'string' && /\bapi\.openai\.com\b/i.test(urlStr)) {
    return true
  }
  if (typeof modelId === 'string') {
    const clean = modelId.trim()
    if (/^(?:gpt-\d|o\d+(?:-|$)|chatgpt-|codex-)/i.test(clean)) return true
  }
  return false
}

function normalizeOpenAiChatModelId(rawModelId, hasTools = false) {
  const clean = String(rawModelId || '').trim()
  if (!clean) return clean
  const lower = clean.toLowerCase()
  const mapped = OPENAI_CHAT_MODEL_ALIASES[lower] || clean
  if (hasTools) {
    return OPENAI_CHAT_TOOLS_MODEL_MAP[mapped.toLowerCase()] || mapped
  }
  return mapped
}

const GEMINI_SKIP_THOUGHT_SIGNATURE = 'skip_thought_signature_validator'
const thoughtSignatureCache = new Map()
const geminiModelUnavailableUntil = new Map()
const openAiModelUnavailableUntil = new Map()

function isDeepSeekOfficialUrl(urlStr) {
  return typeof urlStr === 'string' && /\bapi\.deepseek\.com\b/i.test(urlStr)
}

function isGoogleGeminiEndpoint(urlStr, modelId) {
  if (typeof urlStr === 'string') {
    if (
      /\bgenerativelanguage\.googleapis\.com\b/i.test(urlStr) ||
      /\/v1beta\/openai\b/i.test(urlStr)
    ) {
      return true
    }
  }
  if (typeof modelId === 'string') {
    const clean = modelId.replace(/^models\//i, '').trim()
    if (/^gemini-/i.test(clean)) return true
  }
  return false
}

function normalizeGeminiChatModelId(rawModelId, isGoogleHost = false) {
  const clean = String(rawModelId || '')
    .trim()
    .replace(/^models\//i, '')
  if (!clean) return 'gemini-3-flash-preview'
  if (/live/i.test(clean)) {
    const lower = clean.toLowerCase()
    if (lower === 'gemini-3.8-live' || lower === 'gemini-3.8-live-extended-thinking') {
      return 'gemini-3.8-flash'
    }
    if (lower === 'gemini-3.1-flash-live-preview') {
      return 'gemini-3.1-flash-lite-preview'
    }
    const verMatch = /^gemini-(\d+(?:\.\d+)?)-live(?:-.*)?$/i.exec(clean)
    if (verMatch) {
      return `gemini-${verMatch[1]}-flash`
    }
    return 'gemini-flash-latest'
  }
  if (isGoogleHost && !/^(?:gemini|gemma)-/i.test(clean)) {
    const envModel = String(process.env.DSH_MODEL || '')
      .trim()
      .replace(/^models\//i, '')
    if (/^(?:gemini|gemma)-/i.test(envModel) && !/live/i.test(envModel)) {
      return envModel
    }
    return 'gemini-3.8-flash'
  }
  return clean
}

function unwrapJsonArrayErrorBody(rawText) {
  if (typeof rawText !== 'string') return rawText
  const trimmed = rawText.trim()
  if (!trimmed.startsWith('[')) return rawText
  try {
    const parsed = JSON.parse(trimmed)
    if (Array.isArray(parsed) && parsed.length > 0 && parsed[0] && typeof parsed[0] === 'object') {
      const first = parsed[0]
      if (first.error && typeof first.error === 'object') {
        return JSON.stringify(first)
      }
    }
  } catch {
    /* keep original text */
  }
  return rawText
}

function sanitizeOpenAiChatPayload(rawBody, urlStr, sigCache = thoughtSignatureCache) {
  if (typeof rawBody !== 'string' || !rawBody.trim().startsWith('{')) {
    return { body: rawBody, isGemini: false, parsed: null }
  }
  if (isDeepSeekOfficialUrl(urlStr)) {
    return { body: rawBody, isGemini: false, parsed: null }
  }
  let parsed
  try {
    parsed = JSON.parse(rawBody)
  } catch {
    return { body: rawBody, isGemini: false, parsed: null }
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { body: rawBody, isGemini: false, parsed: null }
  }

  const isGemini = isGoogleGeminiEndpoint(urlStr, parsed.model)
  const thinkingType = parsed.thinking?.type
  delete parsed.thinking
  for (const key of Object.keys(parsed)) {
    if (key.startsWith('dsh_')) {
      delete parsed[key]
    }
  }

  if (isGemini) {
    const isGoogleHost =
      typeof urlStr === 'string' && /\bgenerativelanguage\.googleapis\.com\b/i.test(urlStr)
    parsed.model = normalizeGeminiChatModelId(parsed.model, isGoogleHost)
    const blockedUntil = geminiModelUnavailableUntil.get(parsed.model)
    if (typeof blockedUntil === 'number' && blockedUntil > Date.now()) {
      const replacement = GEMINI_CHAT_FALLBACK_MODELS.find((candidate) => {
        const until = geminiModelUnavailableUntil.get(candidate)
        return !(typeof until === 'number' && until > Date.now())
      })
      if (replacement) parsed.model = replacement
    }
    // Let Gemini use its native dynamic thinking budget instead of forcing high latency or failing on non-thinking models.
    delete parsed.reasoning_effort
    if (
      parsed.max_tokens === 256000 ||
      (typeof parsed.max_tokens === 'number' && parsed.max_tokens > 65536)
    ) {
      delete parsed.max_tokens
    }
  } else {
    const isOpenAi = isOpenAiEndpoint(urlStr, parsed.model)
    const hasTools = Array.isArray(parsed.tools) && parsed.tools.length > 0
    if (isOpenAi && typeof parsed.model === 'string') {
      parsed.model = normalizeOpenAiChatModelId(parsed.model, hasTools)
      const blockedUntil = openAiModelUnavailableUntil.get(parsed.model)
      if (typeof blockedUntil === 'number' && blockedUntil > Date.now()) {
        const replacement = OPENAI_CHAT_FALLBACK_MODELS.find((candidate) => {
          const until = openAiModelUnavailableUntil.get(candidate)
          return !(typeof until === 'number' && until > Date.now())
        })
        if (replacement) parsed.model = replacement
      }
    }
    if (thinkingType === 'disabled') {
      delete parsed.reasoning_effort
    } else if (parsed.reasoning_effort === 'max') {
      parsed.reasoning_effort = 'high'
    }
    if (
      isOpenAi &&
      typeof parsed.model === 'string' &&
      /^(?:gpt-(?:[5-9]|\d{2,})|o\d+)/i.test(parsed.model)
    ) {
      delete parsed.max_tokens
      if (hasTools && /^gpt-(?:[5-9]|\d{2,})/i.test(parsed.model)) {
        parsed.reasoning_effort = 'none'
      }
    } else if (parsed.max_tokens === 256000) {
      delete parsed.max_tokens
    }
  }

  if (isGemini && Array.isArray(parsed.messages)) {
    parsed.messages = parsed.messages.map((msg, idx) => {
      if (!msg || typeof msg !== 'object') return msg
      const copy = { ...msg }
      if (copy.role === 'system' && idx > 0) {
        copy.role = 'user'
        if (typeof copy.content === 'string') {
          copy.content = '[System Reminder]\n' + copy.content
        }
      }
      if (copy.role === 'assistant') {
        const hadReasoning =
          typeof copy.reasoning_content === 'string' && copy.reasoning_content.trim()
            ? copy.reasoning_content.trim()
            : ''
        delete copy.reasoning_content
        if (Array.isArray(copy.tool_calls) && copy.tool_calls.length > 0) {
          copy.tool_calls = copy.tool_calls.map((tc) => {
            if (!tc || typeof tc !== 'object') return tc
            const existingSig = tc.extra_content?.google?.thought_signature
            const cachedSig =
              typeof tc.id === 'string' && tc.id && sigCache ? sigCache.get(tc.id) : undefined
            const sig = existingSig || cachedSig || GEMINI_SKIP_THOUGHT_SIGNATURE
            return {
              ...tc,
              extra_content: {
                ...(tc.extra_content && typeof tc.extra_content === 'object'
                  ? tc.extra_content
                  : {}),
                google: {
                  ...(tc.extra_content?.google && typeof tc.extra_content.google === 'object'
                    ? tc.extra_content.google
                    : {}),
                  thought_signature: sig
                }
              }
            }
          })
        } else if (typeof copy.content !== 'string' || copy.content === '') {
          copy.content = hadReasoning || ' '
        }
      }
      return copy
    })
  }

  return {
    body: JSON.stringify(parsed),
    isGemini,
    parsed
  }
}

function transformGeminiSsePayload(payloadStr, state, sigCache = thoughtSignatureCache) {
  if (typeof payloadStr !== 'string' || !payloadStr.startsWith('{')) return payloadStr
  let chunk
  try {
    chunk = JSON.parse(payloadStr)
  } catch {
    return payloadStr
  }
  if (!chunk || typeof chunk !== 'object') return payloadStr

  if (Array.isArray(chunk.choices)) {
    for (const choice of chunk.choices) {
      if (!choice || typeof choice !== 'object') continue
      const toolCalls = choice.delta?.tool_calls
      if (Array.isArray(toolCalls)) {
        for (const call of toolCalls) {
          if (!call || typeof call !== 'object') continue
          const sig = call.extra_content?.google?.thought_signature
          if (
            typeof call.id === 'string' &&
            call.id &&
            typeof sig === 'string' &&
            sig &&
            sigCache
          ) {
            sigCache.set(call.id, sig)
          }
          if (typeof call.index !== 'number') {
            if (typeof call.id === 'string' && call.id) {
              if (state.toolIdToIndex.has(call.id)) {
                call.index = state.toolIdToIndex.get(call.id)
              } else {
                const idx = state.nextToolCallIndex++
                state.toolIdToIndex.set(call.id, idx)
                call.index = idx
              }
            } else {
              call.index = Math.max(0, state.nextToolCallIndex - 1)
            }
          }
        }
      }
      if (typeof choice.finish_reason === 'string' && choice.finish_reason) {
        const lowerReason = choice.finish_reason.toLowerCase()
        if (lowerReason === 'stop') choice.finish_reason = 'stop'
        else if (lowerReason === 'tool_calls' || lowerReason === 'function_call') {
          choice.finish_reason = 'tool_calls'
        } else if (lowerReason === 'length' || lowerReason === 'max_tokens') {
          choice.finish_reason = 'length'
        }
        state.sawFinishReason = true
      }
    }
  }

  if (chunk.usage && typeof chunk.usage === 'object') {
    const p = chunk.usage.prompt_tokens
    const c = chunk.usage.completion_tokens
    const t = chunk.usage.total_tokens
    if (typeof p === 'number' && typeof c === 'number' && typeof t === 'number' && t > p + c) {
      const thinkingTokens = t - (p + c)
      chunk.usage.completion_tokens_details = {
        ...(chunk.usage.completion_tokens_details &&
        typeof chunk.usage.completion_tokens_details === 'object'
          ? chunk.usage.completion_tokens_details
          : {}),
        reasoning_tokens: chunk.usage.completion_tokens_details?.reasoning_tokens ?? thinkingTokens
      }
      chunk.usage.completion_tokens = c + thinkingTokens
    }
  }

  return JSON.stringify(chunk)
}

function wrapGeminiSseResponse(response, sigCache = thoughtSignatureCache) {
  if (!response?.body || typeof TransformStream === 'undefined') return response
  const state = {
    nextToolCallIndex: 0,
    toolIdToIndex: new Map(),
    sawDone: false,
    sawFinishReason: false
  }
  let lineBuf = ''

  const processLine = (rawLine, controller) => {
    const line = rawLine.endsWith('\r') ? rawLine.slice(0, -1) : rawLine
    if (line.startsWith('data:')) {
      const payload = line.slice(5).trim()
      if (payload === '[DONE]') {
        state.sawDone = true
        controller.enqueue('data: [DONE]\n')
        return
      }
      if (payload.startsWith('{')) {
        const transformed = transformGeminiSsePayload(payload, state, sigCache)
        controller.enqueue('data: ' + transformed + '\n')
        return
      }
    }
    controller.enqueue(rawLine + '\n')
  }

  const sseTransform = new TransformStream({
    transform(chunk, controller) {
      lineBuf += chunk
      const lines = lineBuf.split('\n')
      lineBuf = lines.pop() ?? ''
      for (const rawLine of lines) {
        processLine(rawLine, controller)
      }
    },
    flush(controller) {
      if (lineBuf.trim().length > 0) {
        processLine(lineBuf, controller)
        controller.enqueue('\n')
      }
      if (!state.sawDone && state.sawFinishReason) {
        controller.enqueue('\ndata: [DONE]\n\n')
      }
    }
  })

  const transformedBody = response.body
    .pipeThrough(new TextDecoderStream())
    .pipeThrough(sseTransform)
    .pipeThrough(new TextEncoderStream())

  return new Response(transformedBody, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers
  })
}

function shouldFallbackGeminiModel(status, rawErrorText) {
  if (status === 503 || status === 502 || status === 504 || status === 404 || status === 429) {
    return true
  }
  if (status === 400 && typeof rawErrorText === 'string') {
    return /not found|not supported|bidiGenerateContent|no longer available|unknown model|invalid model/i.test(
      rawErrorText
    )
  }
  return false
}

function shouldFallbackOpenAiModel(status, rawErrorText) {
  if (status === 404) return true
  if ((status === 400 || status === 403) && typeof rawErrorText === 'string') {
    return /does not exist or you do not have access to it|model_not_found|Function tools with reasoning_effort are not supported|is not supported with the\s*'reasoning_effort'|unknown model|invalid model/i.test(
      rawErrorText
    )
  }
  return false
}

function installOpenAiCompatFetchBridge() {
  const FETCH_MARK = Symbol.for('aiart.openAiCompatFetch.patched')
  if (typeof globalThis.fetch !== 'function' || globalThis.fetch[FETCH_MARK]) return
  const originalFetch = globalThis.fetch.bind(globalThis)

  const patchedFetch = async function (input, init) {
    let urlStr =
      typeof input === 'string'
        ? input
        : input && typeof input.url === 'string'
          ? input.url
          : String(input)
    const envBaseUrl = String(process.env.DEEPSEEK_BASE_URL || '')
      .trim()
      .replace(/\/+$/, '')
    if (
      envBaseUrl &&
      !isDeepSeekOfficialUrl(envBaseUrl) &&
      isDeepSeekOfficialUrl(urlStr) &&
      /\/(?:chat\/completions|files)(?:\?.*)?$/i.test(urlStr)
    ) {
      const suffixMatch = /(\/(?:chat\/completions|files)(?:\?.*)?)$/i.exec(urlStr)
      if (suffixMatch) {
        urlStr = envBaseUrl + suffixMatch[1]
        if (typeof input === 'string') {
          input = urlStr
        }
      }
    }
    const method = String(
      init?.method || (input && typeof input === 'object' && input.method) || 'GET'
    ).toUpperCase()

    // Non-DeepSeek endpoints do not implement DeepSeek's proprietary /files upload API;
    // returning 404 immediately lets dsh-llm-deepseek fall back to inline base64 images with zero network delay.
    if (method === 'POST' && !isDeepSeekOfficialUrl(urlStr) && /\/files(?:\?.*)?$/i.test(urlStr)) {
      return new Response(
        JSON.stringify({
          error: { message: 'Files API not supported on this OpenAI-compatible endpoint' }
        }),
        {
          status: 404,
          headers: { 'content-type': 'application/json' }
        }
      )
    }

    if (
      method === 'POST' &&
      typeof init?.body === 'string' &&
      /\/chat\/completions(?:\?.*)?$/i.test(urlStr)
    ) {
      const { body, isGemini, parsed } = sanitizeOpenAiChatPayload(
        init.body,
        urlStr,
        thoughtSignatureCache
      )
      let response = await originalFetch(input, { ...init, body })

      if (isGemini && !response.ok && parsed && typeof parsed.model === 'string') {
        const firstErrText = await response.text()
        if (shouldFallbackGeminiModel(response.status, firstErrText)) {
          geminiModelUnavailableUntil.set(parsed.model, Date.now() + 5 * 60_000)
          const tried = new Set([parsed.model])
          for (const candidateModel of GEMINI_CHAT_FALLBACK_MODELS) {
            if (tried.has(candidateModel)) continue
            tried.add(candidateModel)
            const retryPayload = JSON.stringify({ ...parsed, model: candidateModel })
            const retryResp = await originalFetch(input, { ...init, body: retryPayload })
            if (retryResp.ok) {
              return wrapGeminiSseResponse(retryResp, thoughtSignatureCache)
            }
            const retryErrText = await retryResp.text()
            if (shouldFallbackGeminiModel(retryResp.status, retryErrText)) {
              geminiModelUnavailableUntil.set(candidateModel, Date.now() + 5 * 60_000)
            }
            response = new Response(unwrapJsonArrayErrorBody(retryErrText), {
              status: retryResp.status,
              statusText: retryResp.statusText,
              headers: retryResp.headers
            })
            if (!shouldFallbackGeminiModel(retryResp.status, retryErrText)) {
              break
            }
          }
          return response
        }
        return new Response(unwrapJsonArrayErrorBody(firstErrText), {
          status: response.status,
          statusText: response.statusText,
          headers: response.headers
        })
      }

      if (!response.ok) {
        const errText = await response.text()
        if (
          !isGemini &&
          parsed &&
          typeof parsed.model === 'string' &&
          isOpenAiEndpoint(urlStr, parsed.model) &&
          shouldFallbackOpenAiModel(response.status, errText)
        ) {
          openAiModelUnavailableUntil.set(parsed.model, Date.now() + 5 * 60_000)
          const hasTools = Array.isArray(parsed.tools) && parsed.tools.length > 0
          const tried = new Set([parsed.model])
          for (const candidateModel of OPENAI_CHAT_FALLBACK_MODELS) {
            if (tried.has(candidateModel)) continue
            tried.add(candidateModel)
            const nextPayload = { ...parsed, model: candidateModel }
            delete nextPayload.max_tokens
            if (hasTools && /^gpt-[56]/i.test(candidateModel)) {
              nextPayload.reasoning_effort = 'none'
            }
            const retryResp = await originalFetch(input, {
              ...init,
              body: JSON.stringify(nextPayload)
            })
            if (retryResp.ok) {
              return retryResp
            }
            const retryErrText = await retryResp.text()
            if (shouldFallbackOpenAiModel(retryResp.status, retryErrText)) {
              openAiModelUnavailableUntil.set(candidateModel, Date.now() + 5 * 60_000)
            }
            response = new Response(unwrapJsonArrayErrorBody(retryErrText), {
              status: retryResp.status,
              statusText: retryResp.statusText,
              headers: retryResp.headers
            })
            if (!shouldFallbackOpenAiModel(retryResp.status, retryErrText)) {
              break
            }
          }
          return response
        }
        return new Response(unwrapJsonArrayErrorBody(errText), {
          status: response.status,
          statusText: response.statusText,
          headers: response.headers
        })
      }

      if (isGemini) {
        return wrapGeminiSseResponse(response, thoughtSignatureCache)
      }
      return response
    }

    return originalFetch(input, init)
  }

  patchedFetch[FETCH_MARK] = true
  globalThis.fetch = patchedFetch
}

installOpenAiCompatFetchBridge()

const DSML_OPEN_RE = /<\s*[｜|]\s*DSML\s*[｜|]\s*(?:function_calls|calls|invoke)\b/i
const DSML_PARTIAL_SUFFIX_RE = /<\s*(?:[｜|]\s*(?:D(?:S(?:M(?:L(?:\s*[｜|]\s*[a-z_]*)?)?)?)?)?)?$/i

let dsmlCallSeq = 0

function stripDsmlFromText(text) {
  if (typeof text !== 'string' || text === '') return ''
  const m = DSML_OPEN_RE.exec(text)
  if (!m) return text
  return text.slice(0, m.index).replace(/\s+$/, '')
}

function parseDsmlToolCalls(dsmlText, availableTools) {
  if (typeof dsmlText !== 'string' || !dsmlText.trim()) return []
  const toolList = Array.isArray(availableTools) ? availableTools : []
  const toolByName = new Map()
  for (const t of toolList) {
    if (t && typeof t.name === 'string') toolByName.set(t.name, t)
  }
  const resolveTool = (rawName) => {
    if (toolByName.has(rawName)) return { name: rawName, schema: toolByName.get(rawName) }
    if (!rawName.startsWith('mcp__studio__') && toolByName.has('mcp__studio__' + rawName)) {
      const full = 'mcp__studio__' + rawName
      return { name: full, schema: toolByName.get(full) }
    }
    if (rawName.startsWith('mcp__studio__')) {
      const short = rawName.slice('mcp__studio__'.length)
      if (toolByName.has(short)) return { name: short, schema: toolByName.get(short) }
    }
    return { name: rawName, schema: undefined }
  }

  const ARRAY_OR_OBJECT_PARAM_NAMES = new Set([
    'ops',
    'operations',
    'edits',
    'params',
    'data',
    'patch',
    'plan',
    'steps',
    'questions',
    'todos',
    'files',
    'position',
    'positionDelta',
    'rotation',
    'rotationDeg',
    'rotationDeltaDeg',
    'scale',
    'target',
    'cinemachine',
    'handheldShake',
    'environment',
    'sceneWorld',
    'ground',
    'light',
    'bonePose',
    'styleImages',
    'referenceImageUrls',
    'inputReferences'
  ])

  const calls = []
  const invokeRe =
    /<\s*[｜|]\s*DSML\s*[｜|]\s*invoke\b([^>]*)>([\s\S]*?)(?:<\s*\/\s*[｜|]\s*DSML\s*[｜|]\s*invoke\s*>|(?=<\s*[｜|]\s*DSML\s*[｜|]\s*invoke\b)|<\s*\/\s*[｜|]\s*DSML\s*[｜|]\s*(?:function_calls|calls)\s*>|$)/gi
  let m
  while ((m = invokeRe.exec(dsmlText)) !== null) {
    const attrText = m[1] || ''
    const bodyText = m[2] || ''
    const nameMatch = /\bname\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s>]+))/i.exec(attrText)
    const rawName = (nameMatch?.[1] ?? nameMatch?.[2] ?? nameMatch?.[3] ?? '').trim()
    if (!rawName) continue
    const { name: resolvedName, schema } = resolveTool(rawName)
    const propSchemas =
      schema?.parameters?.properties && typeof schema.parameters.properties === 'object'
        ? schema.parameters.properties
        : {}

    const argsObj = {}
    let paramCount = 0
    const paramRe =
      /<\s*[｜|]\s*DSML\s*[｜|]\s*parameter\b([^>]*)>([\s\S]*?)(?:<\s*\/\s*[｜|]\s*DSML\s*[｜|]\s*parameter\s*>|(?=<\s*[｜|]\s*DSML\s*[｜|]\s*parameter\b)|<\s*\/\s*[｜|]\s*DSML\s*[｜|]\s*(?:invoke|function_calls|calls)\s*>|$)/gi
    let pm
    while ((pm = paramRe.exec(bodyText)) !== null) {
      const pAttr = pm[1] || ''
      const rawVal = pm[2] ?? ''
      const pNameMatch = /\bname\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s>]+))/i.exec(pAttr)
      const paramName = (pNameMatch?.[1] ?? pNameMatch?.[2] ?? pNameMatch?.[3] ?? '').trim()
      if (!paramName) continue
      paramCount += 1
      const pStrMatch = /\bstring\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s>]+))/i.exec(pAttr)
      const stringFlag = (pStrMatch?.[1] ?? pStrMatch?.[2] ?? pStrMatch?.[3] ?? '')
        .trim()
        .toLowerCase()
      const propType = propSchemas?.[paramName]?.type
      const trimmedVal = rawVal.trim()
      const shouldParseJson =
        stringFlag === 'false' ||
        propType === 'array' ||
        propType === 'object' ||
        propType === 'number' ||
        propType === 'integer' ||
        propType === 'boolean' ||
        ARRAY_OR_OBJECT_PARAM_NAMES.has(paramName) ||
        (stringFlag === '' &&
          propType !== 'string' &&
          (/^[\[{]/.test(trimmedVal) || /^(?:true|false|null|-?\d+(?:\.\d+)?)$/.test(trimmedVal)))

      if (shouldParseJson) {
        try {
          argsObj[paramName] = JSON.parse(trimmedVal)
          continue
        } catch {
          /* fallback to string */
        }
      }
      argsObj[paramName] = rawVal.replace(/^\r?\n/, '').replace(/\r?\n$/, '')
    }

    if (paramCount === 0) {
      const cleanBody = bodyText.replace(/<\s*\/?\s*[｜|]\s*DSML\s*[｜|][^>]*>/gi, '').trim()
      if (cleanBody.startsWith('{')) {
        try {
          const parsedBody = JSON.parse(cleanBody)
          if (parsedBody && typeof parsedBody === 'object' && !Array.isArray(parsedBody)) {
            Object.assign(argsObj, parsedBody)
          }
        } catch {
          /* ignore */
        }
      }
    }

    calls.push({
      id: 'call_dsml_' + Date.now().toString(36) + '_' + ++dsmlCallSeq,
      name: resolvedName,
      arguments: JSON.stringify(argsObj)
    })
  }
  return calls
}

async function* wrapDsmlStream(source, options, getMode) {
  const textBlocks = new Map()
  const pendingToolCalls = []
  let nativeToolCallCount = 0
  let nonTextBlocksOpened = 0
  let anyTextBlockOpened = false
  let maxBlockIndex = -1
  let flushedToolCalls = false
  let synthesizedToolCallCount = 0

  const flushSynthesizedToolCalls = function* () {
    if (flushedToolCalls) return
    flushedToolCalls = true
    if (
      pendingToolCalls.length === 0 ||
      nativeToolCallCount > 0 ||
      (typeof getMode === 'function' && getMode() === 'ask')
    ) {
      return
    }
    for (const call of pendingToolCalls) {
      const idx = ++maxBlockIndex
      synthesizedToolCallCount += 1
      yield {
        type: 'block-start',
        index: idx,
        blockType: 'tool-call'
      }
      yield {
        type: 'tool-call-delta',
        index: idx,
        id: call.id,
        name: call.name,
        argumentsDelta: call.arguments
      }
      yield {
        type: 'block-end',
        index: idx,
        block: {
          type: 'tool-call',
          id: call.id,
          name: call.name,
          arguments: call.arguments
        }
      }
    }
  }

  for await (const chunk of source) {
    if (typeof chunk?.index === 'number' && chunk.index > maxBlockIndex) {
      maxBlockIndex = chunk.index
    }

    if (chunk.type === 'block-start') {
      if (chunk.blockType === 'text') {
        textBlocks.set(chunk.index, {
          rawText: '',
          emittedLen: 0,
          opened: false,
          dsmlStartIdx: -1
        })
        continue
      }
      if (chunk.blockType === 'tool-call') {
        nativeToolCallCount += 1
      }
      nonTextBlocksOpened += 1
      yield chunk
      continue
    }

    if (chunk.type === 'text-delta') {
      let state = textBlocks.get(chunk.index)
      if (!state) {
        state = { rawText: '', emittedLen: 0, opened: false, dsmlStartIdx: -1 }
        textBlocks.set(chunk.index, state)
      }
      state.rawText += chunk.text ?? ''
      if (state.dsmlStartIdx < 0) {
        const m = DSML_OPEN_RE.exec(state.rawText)
        if (m) {
          state.dsmlStartIdx = m.index
        }
      }
      if (state.dsmlStartIdx >= 0) {
        const safeSlice = state.rawText
          .slice(state.emittedLen, state.dsmlStartIdx)
          .replace(/\s+$/, '')
        if (safeSlice.length > 0 && (state.opened || safeSlice.trim() !== '')) {
          if (!state.opened) {
            state.opened = true
            anyTextBlockOpened = true
            yield { type: 'block-start', index: chunk.index, blockType: 'text' }
          }
          yield { type: 'text-delta', index: chunk.index, text: safeSlice }
        }
        state.emittedLen = state.dsmlStartIdx
        continue
      }

      const unemitted = state.rawText.slice(state.emittedLen)
      const partialMatch = DSML_PARTIAL_SUFFIX_RE.exec(unemitted)
      const safeEnd = partialMatch ? state.emittedLen + partialMatch.index : state.rawText.length
      const toEmit = state.rawText.slice(state.emittedLen, safeEnd)
      if (toEmit.length > 0 && (state.opened || toEmit.trim() !== '')) {
        if (!state.opened) {
          state.opened = true
          anyTextBlockOpened = true
          yield { type: 'block-start', index: chunk.index, blockType: 'text' }
        }
        state.emittedLen = safeEnd
        yield { type: 'text-delta', index: chunk.index, text: toEmit }
      }
      continue
    }

    if (
      chunk.type === 'block-end' &&
      (chunk.block?.type === 'text' || textBlocks.has(chunk.index))
    ) {
      const state = textBlocks.get(chunk.index)
      textBlocks.delete(chunk.index)
      if (!state) {
        yield chunk
        continue
      }
      if (state.dsmlStartIdx < 0) {
        const m = DSML_OPEN_RE.exec(state.rawText)
        if (m) state.dsmlStartIdx = m.index
      }
      if (state.dsmlStartIdx >= 0) {
        const visibleText = state.rawText.slice(0, state.dsmlStartIdx).replace(/\s+$/, '')
        const dsmlPayload = state.rawText.slice(state.dsmlStartIdx)
        const parsedCalls = parseDsmlToolCalls(dsmlPayload, options?.tools)
        pendingToolCalls.push(...parsedCalls)

        if (visibleText.length > state.emittedLen) {
          const rem = visibleText.slice(state.emittedLen)
          if (rem.length > 0 && (state.opened || rem.trim() !== '')) {
            if (!state.opened) {
              state.opened = true
              anyTextBlockOpened = true
              yield { type: 'block-start', index: chunk.index, blockType: 'text' }
            }
            yield { type: 'text-delta', index: chunk.index, text: rem }
          }
        }
        if (state.opened) {
          yield {
            type: 'block-end',
            index: chunk.index,
            block: { type: 'text', text: visibleText }
          }
        } else if (
          parsedCalls.length === 0 &&
          pendingToolCalls.length === 0 &&
          nonTextBlocksOpened === 0 &&
          !anyTextBlockOpened
        ) {
          state.opened = true
          anyTextBlockOpened = true
          yield { type: 'block-start', index: chunk.index, blockType: 'text' }
          yield {
            type: 'block-end',
            index: chunk.index,
            block: { type: 'text', text: visibleText }
          }
        }
        continue
      }

      const rem = state.rawText.slice(state.emittedLen)
      if (!state.opened) {
        state.opened = true
        anyTextBlockOpened = true
        yield { type: 'block-start', index: chunk.index, blockType: 'text' }
      }
      if (rem.length > 0) {
        yield { type: 'text-delta', index: chunk.index, text: rem }
      }
      yield {
        type: 'block-end',
        index: chunk.index,
        block: { type: 'text', text: state.rawText }
      }
      continue
    }

    if (chunk.type === 'usage') {
      yield* flushSynthesizedToolCalls()
      yield chunk
      continue
    }

    if (chunk.type === 'finish') {
      if (
        textBlocks.size > 0 &&
        chunk.reason?.kind !== 'error' &&
        chunk.reason?.kind !== 'aborted'
      ) {
        for (const [idx, state] of textBlocks.entries()) {
          if (state.opened) {
            const visibleText =
              state.dsmlStartIdx >= 0
                ? state.rawText.slice(0, state.dsmlStartIdx).replace(/\s+$/, '')
                : state.rawText
            yield {
              type: 'block-end',
              index: idx,
              block: { type: 'text', text: visibleText }
            }
          }
        }
        textBlocks.clear()
      }
      yield* flushSynthesizedToolCalls()
      if (synthesizedToolCallCount > 0 && chunk.reason?.kind === 'stop') {
        yield {
          ...chunk,
          reason: { kind: 'tool-calls' }
        }
      } else {
        yield chunk
      }
      continue
    }

    yield chunk
  }
}

function registerDsmlStreamTranspiler(ctx, getMode) {
  if (typeof ctx?.on !== 'function') return
  ctx.on('llm/stream', (options, next) => wrapDsmlStream(next(), options, getMode), {
    global: true
  })
}

function summarize(session, firstSeq) {
  let started = false
  let text = ''
  let reason
  for (let seq = firstSeq; seq <= session.seq; seq++) {
    const event = session.eventAt(SessionSeq(seq))
    if (event === void 0) continue
    if (event.type === 'turn/start') {
      started = true
      continue
    }
    if (!started) continue
    if (event.type === 'assistant/message') {
      const content = event.data?.message?.content ?? []
      const joined = content
        .filter((block) => block.type === 'text')
        .map((block) => stripDsmlFromText(block.text))
        .join('')
      if (joined !== '') text = joined
    }
    if (event.type === 'turn/end') reason = event.data.reason
  }
  return { text, reason }
}

function imageMediaType(path) {
  const m = /\.([a-z0-9]+)$/i.exec(path)
  const ext = m ? m[1].toLowerCase() : ''
  if (ext === 'png') return 'image/png'
  if (ext === 'jpg' || ext === 'jpeg') return 'image/jpeg'
  if (ext === 'webp') return 'image/webp'
  if (ext === 'gif') return 'image/gif'
  return null
}

function sniffBufferImageMediaType(buf) {
  if (!buf || buf.length < 3) return null
  if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'image/jpeg'
  if (
    buf.length >= 8 &&
    buf[0] === 0x89 &&
    buf[1] === 0x50 &&
    buf[2] === 0x4e &&
    buf[3] === 0x47 &&
    buf[4] === 0x0d &&
    buf[5] === 0x0a &&
    buf[6] === 0x1a &&
    buf[7] === 0x0a
  ) {
    return 'image/png'
  }
  if (
    buf.length >= 6 &&
    buf[0] === 0x47 &&
    buf[1] === 0x49 &&
    buf[2] === 0x46 &&
    buf[3] === 0x38 &&
    (buf[4] === 0x37 || buf[4] === 0x39) &&
    buf[5] === 0x61
  ) {
    return 'image/gif'
  }
  if (
    buf.length >= 12 &&
    buf[0] === 0x52 &&
    buf[1] === 0x49 &&
    buf[2] === 0x46 &&
    buf[3] === 0x46 &&
    buf[8] === 0x57 &&
    buf[9] === 0x45 &&
    buf[10] === 0x42 &&
    buf[11] === 0x50
  ) {
    return 'image/webp'
  }
  return null
}

const MAX_USER_IMAGES = 20

async function buildUserContent(task, attachments, io) {
  const blocks = []
  const cwd = process.cwd()
  let last = 0
  let imageCount = 0
  const refRe = /@(?:(image:)\s*)?([^\s@]+)/g
  let m
  while ((m = refRe.exec(task)) !== null) {
    const prefix = m[1] ?? ''
    const raw = m[2]
    const path = raw.replace(/\\/g, '/')
    const before = task.slice(last, m.index)
    last = m.index + m[0].length
    const mediaType = imageMediaType(path)
    const canAttach = mediaType !== null && imageCount < MAX_USER_IMAGES && attachments?.saveImage
    if (!canAttach) {
      if (before !== '') blocks.push({ type: 'text', text: before })
      blocks.push({ type: 'text', text: '@' + prefix + raw })
      continue
    }
    imageCount += 1
    if (before !== '') blocks.push({ type: 'text', text: before })
    try {
      const abs = resolve(cwd, path)
      if (!abs.startsWith(cwd + sep)) throw new Error('path escapes workspace')
      const buf = readFileSync(abs)
      const actualMediaType = sniffBufferImageMediaType(buf) || mediaType
      const attachment = await attachments.saveImage({
        data: buf,
        mediaType: actualMediaType,
        name: path.split('/').pop()
      })
      blocks.push({ type: 'image', attachment })
      blocks.push({ type: 'text', text: '@' + prefix + raw })
    } catch (error) {
      io.stderr.write(
        '[aiart-runner] image attach failed ' +
          raw +
          ': ' +
          (error instanceof Error ? error.message : String(error)) +
          '\n'
      )
      blocks.push({ type: 'text', text: '@' + prefix + raw })
    }
  }
  const rest = task.slice(last)
  if (rest !== '') blocks.push({ type: 'text', text: rest })
  return blocks
}

function modePreamble(mode) {
  if (mode === 'ask') {
    return (
      '[AIArtEngine panel mode: Ask]\n' +
      'Answer in text only. Do not call tools or modify files.\n\n'
    )
  }
  if (mode === 'plan') {
    return (
      '[AIArtEngine panel mode: Plan]\n' +
      'First outline a concise plan, then call ask_user_question to confirm before any write/generate tools.\n\n'
    )
  }
  return '[AIArtEngine panel mode: Craft]\nPrefer MCP tools to complete the request.\n\n'
}

/** Tools that start a child agent; their callId anchors the child's activity in the panel. */
const DELEGATION_TOOLS = new Set(['subagent', 'subagent_fork'])
/** Every subagent tool, including the ones that steer an existing child. */
const SUBAGENT_TOOLS = new Set([
  ...DELEGATION_TOOLS,
  'send_message',
  'interrupt_agent',
  'list_agents'
])

const ASK_DELEGATION_DENIED =
  'Ask mode does not allow delegating to subagents; answer in text only.'
const CHILD_ASK_USER_DENIED =
  'Delegated subagents cannot ask the user. Put the open question in your reply so the delegating agent can ask it.'

function childModeNote(mode) {
  if (mode === 'plan') {
    return (
      '[AIArtEngine panel mode: Plan]\n' +
      'Write/generate tools stay locked until the user confirms the plan with the delegating agent. ' +
      'Prefer read-only tools; if a tool is denied, do not retry it — report findings or proposed steps back.'
    )
  }
  return '[AIArtEngine panel mode: Craft]\n' + 'Prefer MCP tools to complete the delegated task.'
}

function delegationDepthOf(agent) {
  const depth = agent?.session?.header?.delegationDepth
  return typeof depth === 'number' ? depth : 0
}

/** Panel mode applies to the whole delegation tree, so the guard is global and keyed by agent depth. */
function registerDelegationGuard(ctx, getMode) {
  const tools = ctx.get('tools')
  if (typeof tools?.guard !== 'function') return
  tools.guard((exec) => {
    if (getMode() === 'ask' && SUBAGENT_TOOLS.has(exec.name)) return ASK_DELEGATION_DENIED
    if (exec.name === 'ask_user_question' && delegationDepthOf(exec.agent) > 0) {
      return CHILD_ASK_USER_DENIED
    }
    return undefined
  })
}

function parseToolArgs(raw) {
  if (raw && typeof raw === 'object') return raw
  if (typeof raw !== 'string' || raw === '') return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

/** `subagent/descriptor` label (the delegation's `description`); undefined until it is appended. */
function descriptorLabel(session, fromSeq) {
  for (let seq = fromSeq; seq < session.seq; seq++) {
    const event = session.eventAt(SessionSeq(seq))
    if (event?.type === 'subagent/descriptor') {
      return typeof event.data?.label === 'string' ? event.data.label : ''
    }
  }
  return undefined
}

/** Last panel mode announced to each child; live children outlive turns, so notes repeat only on change. */
const notedModes = new WeakMap()

function noteChildMode(agent, mode) {
  if (notedModes.get(agent) === mode) return
  notedModes.set(agent, mode)
  agent.inject(
    createUserMessage({
      content: [{ type: 'text', text: childModeNote(mode) }],
      source: { kind: 'plugin', plugin: name }
    })
  )
}

/**
 * Child agents under one panel turn's root agent: those spawned during the turn and
 * those still live from earlier turns (continuable children woken by send_message).
 * Each child is anchored to the top-level call that led to it, so the panel can nest
 * its tool activity under that card.
 */
function createDelegationTracker(ctx, root, mode) {
  const rootSessionId = String(root.session.header.id)
  const children = new Map()
  const delegations = []
  /** send_message target → anchor of that call; re-anchors a child each time it is woken. */
  const wakeAnchors = new Map()

  const ownerOf = (sessionId) => {
    if (sessionId === rootSessionId) return { sessionId, anchorId: undefined, isRoot: true }
    return children.get(sessionId)
  }

  const track = (agent, adopted) => {
    const header = agent?.session?.header
    if (header?.origin !== 'subagent' || header.parentSession === undefined) return undefined
    const sessionId = String(header.id)
    if (children.has(sessionId)) return children.get(sessionId)
    const owner = ownerOf(String(header.parentSession))
    if (owner === undefined) return undefined
    const entry = {
      agent,
      sessionId,
      ownerSessionId: owner.sessionId,
      startSeq: agent.session.seq,
      lastSeq: agent.session.seq,
      pendingTools: new Map(),
      anchorId: undefined,
      label: '',
      role: '',
      toolCount: 0,
      activeTool: '',
      activeToolDetail: '',
      updatedAt: Date.now(),
      resolved: false,
      adopted
    }
    children.set(sessionId, entry)
    return entry
  }

  // Registration order lists parents before their children, so one pass adopts whole subtrees.
  const registry = ctx.get('agents')
  if (typeof registry?.list === 'function') {
    for (const agent of registry.list()) {
      if (track(agent, true)) noteChildMode(agent, mode)
    }
  }

  const offCreated = ctx.on('agent/created', ({ agent }) => {
    track(agent, false)
  })
  const offStart = ctx.on('agent/session-start', ({ agent }) => {
    const header = agent?.session?.header
    if (header === undefined || !children.has(String(header.id))) return
    noteChildMode(agent, mode)
  })
  const offDisposed = ctx.on('agent/disposed', ({ agent }) => {
    const id = agent?.session?.header?.id
    const entry = id === undefined ? undefined : children.get(String(id))
    if (entry) {
      entry.disposed = true
      entry.activeTool = ''
      entry.activeToolDetail = ''
      entry.updatedAt = Date.now()
    }
  })

  /** Remember delegation and wake-up calls so the children they drive can be anchored to them. */
  const noteToolCall = (ownerSessionId, anchorId, callId, toolName, rawArgs) => {
    const args = parseToolArgs(rawArgs)
    const ownerChild = children.get(ownerSessionId)
    if (ownerChild) {
      ownerChild.toolCount = (ownerChild.toolCount || 0) + 1
      ownerChild.activeTool = toolName
      ownerChild.activeToolDetail = summarizeToolArgs(rawArgs)
      ownerChild.updatedAt = Date.now()
    }
    if (toolName === 'send_message') {
      const target = typeof args?.agent_id === 'string' ? args.agent_id : ''
      if (!target) return
      const anchor = anchorId ?? callId
      wakeAnchors.set(target, anchor)
      const child = children.get(target)
      if (child?.resolved) {
        child.anchorId = anchor
        child.updatedAt = Date.now()
      }
      return
    }
    if (!DELEGATION_TOOLS.has(toolName)) return
    delegations.push({
      ownerSessionId,
      callId,
      anchorId: anchorId ?? callId,
      label: typeof args?.description === 'string' ? args.description : '',
      role: typeof args?.agent_type === 'string' ? args.agent_type : toolName,
      claimed: false
    })
  }

  /**
   * Match a child to the call that drives it: a send_message that woke it, else its
   * delegation call (same owner, same description label, falling back to the earliest
   * unclaimed call). Returns false while it is too early to tell.
   */
  const resolveAnchor = (child, force) => {
    if (child.resolved) return true
    const woken = wakeAnchors.get(child.sessionId)
    if (woken !== undefined) {
      child.anchorId = woken
      child.resolved = true
      return true
    }
    // A child from an earlier turn only acts this turn after a send_message reaches it.
    if (child.adopted) {
      if (force) child.resolved = true
      return force
    }
    const owner = ownerOf(child.ownerSessionId)
    if (owner === undefined || (!owner.isRoot && !owner.resolved)) {
      if (!force) return false
    }
    const label = descriptorLabel(child.agent.session, child.startSeq)
    if (label) child.label = label
    const open = delegations.filter((d) => !d.claimed && d.ownerSessionId === child.ownerSessionId)
    const pick = (label ? open.find((d) => d.label === label) : undefined) ?? open[0]
    if (pick === undefined && !force) return false
    if (pick) {
      pick.claimed = true
      child.anchorId = pick.anchorId
      if (!child.label && pick.label) child.label = pick.label
      if (!child.role && pick.role) child.role = pick.role
    }
    child.resolved = true
    return true
  }

  const snapshotSubagents = () => {
    const out = []
    for (const child of children.values()) {
      const desc =
        child.label ||
        descriptorLabel(child.agent?.session, child.startSeq) ||
        child.sessionId.slice(0, 12)
      const status = child.disposed
        ? 'completed'
        : child.agent?.status === 'running'
          ? 'running'
          : 'idle'
      out.push({
        sessionId: child.sessionId,
        parentSessionId: child.ownerSessionId,
        ...(child.anchorId ? { anchorCallId: child.anchorId } : {}),
        label: desc,
        description: desc,
        agentType: child.role || 'subagent',
        ...(child.role ? { role: child.role } : {}),
        status,
        ...(status === 'running' && child.activeTool ? { activeTool: child.activeTool } : {}),
        ...(status === 'running' && child.activeToolDetail
          ? { activeToolDetail: child.activeToolDetail }
          : {}),
        toolCount: child.toolCount || 0,
        updatedAt: child.updatedAt || Date.now()
      })
    }
    return out
  }

  const isBusy = () => {
    for (const child of children.values()) {
      if (!child.disposed && child.agent.status === 'running') return true
    }
    return false
  }

  const whenChildrenIdle = () =>
    Promise.all(
      [...children.values()]
        .filter((child) => !child.disposed)
        .map((child) => child.agent.whenIdle().catch(() => undefined))
    )

  const dispose = () => {
    offCreated()
    offStart()
    offDisposed()
  }

  return {
    children,
    noteToolCall,
    resolveAnchor,
    snapshotSubagents,
    isBusy,
    whenChildrenIdle,
    dispose
  }
}

function registerAskUserTool(ctx, io, getMode, getRunId) {
  const userQuestions = ctx.get('userQuestions')
  const toolsRegistry = ctx.get('tools')
  if (!toolsRegistry?.register) return

  const askSingleQuestion = async (q, signal) => {
    const qId = typeof q?.id === 'string' && q.id ? q.id : 'q1'
    try {
      const runId = getRunId() || 'run'
      const requestId = 'harness:' + runId + ':' + randomUUID()
      const answerFile = join(
        process.env.AIART_ASK_DIR || '',
        'aiart-ask-' + requestId.replace(/[^a-zA-Z0-9_-]/g, '-') + '.json'
      )
      const askPayload = {
        requestId,
        questionId: qId,
        question: typeof q?.question === 'string' ? q.question : '',
        ...(q?.header ? { hint: q.header } : {}),
        options: (q?.options ?? [])
          .map((option) => (typeof option === 'string' ? option : option?.label))
          .filter(Boolean),
        answerFile
      }
      sendIpc({ type: 'ask_user', ...askPayload, payload: askPayload }, () => {
        io.stdout.write('\n' + ASK_USER_BEGIN + JSON.stringify(askPayload) + '\n')
      })
      const deadline = Date.now() + 5 * 60 * 1000
      while (Date.now() < deadline) {
        if (signal?.aborted) return { id: qId, selected: [] }
        try {
          const raw = readFileSync(answerFile, 'utf8')
          const parsed = JSON.parse(raw)
          const firstAns = parsed?.answers?.[0]
          if (firstAns && Array.isArray(firstAns.selected)) {
            return {
              id: qId,
              selected: firstAns.selected.map(String),
              ...(typeof firstAns.custom === 'string' ? { custom: firstAns.custom } : {})
            }
          }
          return { id: qId, selected: [] }
        } catch {
          /* waiting */
        }
        await new Promise((resolve) => setTimeout(resolve, 250))
      }
      return { id: qId, selected: [] }
    } catch (error) {
      io.stderr.write(
        '[aiart-runner] ask-user answerer error: ' +
          (error instanceof Error ? error.message : String(error)) +
          '\n'
      )
      return { id: qId, selected: [] }
    }
  }

  const answerAskUserQuestion = async (request) => {
    const questions = Array.isArray(request?.questions) ? request.questions : []
    if (!questions.length) return { answers: [] }
    const answers = []
    for (const q of questions) {
      if (request?.signal?.aborted) {
        answers.push({ id: typeof q?.id === 'string' && q.id ? q.id : 'q1', selected: [] })
        continue
      }
      const ans = await askSingleQuestion(q, request?.signal)
      answers.push(ans)
    }
    return { answers }
  }

  if (typeof ctx.on === 'function') {
    ctx.on('user-questions/request', (request) =>
      answerAskUserQuestion(request).catch((error) => {
        io.stderr.write(
          '[aiart-runner] root ask-user answerer failed: ' +
            (error instanceof Error ? error.message : String(error)) +
            '\n'
        )
        const questions = Array.isArray(request?.questions) ? request.questions : []
        return {
          answers: questions.map((q, i) => ({
            id: typeof q?.id === 'string' && q.id ? q.id : 'q' + (i + 1),
            selected: []
          }))
        }
      })
    )
  }

  toolsRegistry.register(
    defineTool({
      name: 'ask_user_question',
      description:
        'Ask the user a concise question when you need confirmation, a choice, or missing information before proceeding. Send one or more questions, each with a stable id that will be echoed in the answer.',
      parameters: {
        questions: {
          type: 'array',
          required: true,
          description: 'Questions to ask the user before continuing.',
          items: {
            type: 'object',
            additionalProperties: true,
            properties: {
              id: {
                type: 'string',
                required: true,
                description: 'Stable id for this question; echoed in the answer.'
              },
              question: {
                type: 'string',
                required: true,
                description: 'The specific question to ask the user.'
              },
              header: {
                type: 'string',
                description:
                  'Optional short heading for the question, such as "Confirm" or "Choose Mode".'
              },
              options: {
                type: 'array',
                description:
                  'Optional choices to show the user. If you recommend one, put it first and append "(Recommended)" to that label.',
                items: {
                  type: 'object',
                  additionalProperties: true,
                  properties: {
                    label: {
                      type: 'string',
                      required: true,
                      description: 'Short user-facing option label.'
                    },
                    description: {
                      type: 'string',
                      description: 'One sentence explaining the tradeoff or impact.'
                    }
                  }
                }
              },
              multi_select: {
                type: 'boolean',
                description: 'Whether the user may select more than one option. Defaults to false.'
              }
            }
          }
        }
      },
      output: {
        schema: {
          type: 'object',
          additionalProperties: false,
          properties: {
            answers: {
              type: 'array',
              required: true,
              items: {
                type: 'object',
                additionalProperties: false,
                properties: {
                  id: { type: 'string', required: true },
                  selected: { type: 'array', required: true, items: { type: 'string' } },
                  custom: { type: 'string' }
                }
              }
            }
          }
        },
        render: (_args, value) => [{ type: 'text', text: JSON.stringify(value) }]
      },
      async execute(args, exec) {
        if (getMode() === 'ask') {
          throw new Error('Ask mode does not allow ask_user_question; answer in text only.')
        }
        if (delegationDepthOf(exec.agent) > 0) {
          throw new Error(
            'Subagents cannot call ask_user_question directly; return the unresolved question to the root agent.'
          )
        }
        const normalizedQuestions = (Array.isArray(args?.questions) ? args.questions : []).map(
          (question, idx) => ({
            id: typeof question?.id === 'string' && question.id ? question.id : 'q' + (idx + 1),
            question: typeof question?.question === 'string' ? question.question : '',
            ...(question?.header !== undefined ? { header: question.header } : {}),
            ...(question?.options !== undefined ? { options: question.options } : {}),
            ...(question?.multi_select !== undefined ? { multiSelect: question.multi_select } : {})
          })
        )
        let response
        if (userQuestions) {
          try {
            response = await userQuestions.ask({
              questions: normalizedQuestions,
              ...(exec.agent !== undefined ? { agent: exec.agent } : {}),
              signal: exec.signal
            })
          } catch (err) {
            const code = err && typeof err === 'object' ? err.code : ''
            if (code === 'NO_PROVIDER' || code === 'CALLER_NOT_LIVE') {
              response = await answerAskUserQuestion({
                questions: normalizedQuestions,
                signal: exec.signal
              })
            } else {
              throw err
            }
          }
        } else {
          response = await answerAskUserQuestion({
            questions: normalizedQuestions,
            signal: exec.signal
          })
        }
        return {
          answers: response.answers.map((answer) => ({
            id: answer.id,
            selected: [...answer.selected],
            ...(answer.custom !== undefined ? { custom: answer.custom } : {})
          }))
        }
      }
    })
  )

  return answerAskUserQuestion
}

/** Drop a cached agent and release its session write handle (flush alone is not enough). */
async function releaseAgentSlot(agentSlot) {
  const handle = agentSlot.handle
  agentSlot.handle = undefined
  agentSlot.sessionId = ''
  agentSlot.model = ''
  agentSlot.provider = ''
  if (!handle?.dispose) return
  try {
    await handle.dispose()
  } catch {
    /* ignore — next create/resume must not be blocked by a leaked write lease */
  }
}

async function runOneTurn(ctx, io, opts) {
  const {
    task,
    sessionId: rawSessionId,
    mode,
    runId,
    selection,
    answerAskUserQuestion,
    agentSlot
  } = opts
  const agents = ctx.get('agents')
  const sessions = ctx.get('sessions')
  if (agents === void 0 || sessions === void 0) throw new Error('agents/sessions unavailable')

  const sessionId = (rawSessionId || '').trim() || 'session-' + randomUUID()
  const agentOptions = { provider: selection.provider, model: selection.model }
  const setup = (agentCtx) => {
    installModelSelection(agentCtx, {
      current: selection,
      assembled: void 0
    })
    agentCtx.on('user-questions/request', (request) =>
      answerAskUserQuestion(request).catch((error) => {
        io.stderr.write(
          '[aiart-runner] ask-user answerer failed: ' +
            (error instanceof Error ? error.message : String(error)) +
            '\n'
        )
        const first = request?.questions?.[0]
        return { answers: first ? [{ id: first.id, selected: [] }] : [] }
      })
    )
  }

  let agent = agentSlot.handle?.agent
  const sameSession = agentSlot.sessionId === sessionId
  const sameModel =
    agent && agentSlot.model === selection.model && agentSlot.provider === selection.provider

  if (agent && (!sameSession || !sameModel)) {
    try {
      await sessions.flush(agent.session)
    } catch {
      /* ignore */
    }
    await releaseAgentSlot(agentSlot)
    agent = undefined
  }

  if (agent === undefined) {
    const persistence = ctx.get('sessionPersistence')
    const hasSessionId = !!(rawSessionId || '').trim()
    if (persistence !== void 0 && hasSessionId) {
      const exists =
        typeof persistence.stat === 'function'
          ? (await persistence.stat(SessionId(sessionId))) !== void 0
          : (await persistence.list()).some(
              (entry) => (entry?.id ?? entry?.sessionId ?? entry?.header?.id) === sessionId
            )
      if (exists) {
        try {
          const resumed = await agents.resume({
            resumeSessionId: sessionId,
            agentOptions,
            setup
          })
          agentSlot.handle = resumed
          agent = resumed.agent
          io.stderr.write('[aiart-runner] resumed session: ' + sessionId + '\n')
        } catch (error) {
          // Same-process leak recovery: agent still registered → reuse instead of resume
          const live =
            typeof agents.get === 'function' ? agents.get(SessionId(sessionId)) : undefined
          const owned =
            error instanceof Error && /already owned by an active write handle/i.test(error.message)
          if (owned && live) {
            agentSlot.handle = {
              agent: live,
              // Best-effort teardown: disposing the agent scope runs the loop's
              // tracked disposer, which closes the persistence write handle.
              dispose: async () => {
                try {
                  if (typeof live.cancel === 'function') live.cancel({ kind: 'disposed' })
                } catch {
                  /* ignore */
                }
                try {
                  if (typeof live.whenIdle === 'function') await live.whenIdle()
                } catch {
                  /* ignore */
                }
                try {
                  if (live.scope && typeof live.scope.dispose === 'function') {
                    await live.scope.dispose()
                  }
                } catch {
                  /* ignore */
                }
              }
            }
            agent = live
            io.stderr.write('[aiart-runner] reused live session: ' + sessionId + '\n')
          } else {
            io.stderr.write(
              '[aiart-runner] resume failed: ' +
                (error instanceof Error ? error.message : String(error)) +
                '\n'
            )
            throw error
          }
        }
      }
    }
    if (agent === undefined) {
      const created = await agents.create({
        sessionId: SessionId(sessionId),
        meta: { cwd: process.cwd() },
        agentOptions,
        setup
      })
      agentSlot.handle = created
      agent = created.agent
      if (hasSessionId) io.stderr.write('[aiart-runner] created session: ' + sessionId + '\n')
    }
    agentSlot.sessionId = sessionId
    agentSlot.model = selection.model
    agentSlot.provider = selection.provider
  }

  await agent.whenIdle()
  const firstSeq = agent.session.seq

  let inReasoning = false
  let streamedText = false
  let lastSubagentJson = ''
  const closeReasoning = () => {
    if (inReasoning) {
      inReasoning = false
      sendIpc({ type: 'reasoning_end' }, () => {
        io.stdout.write('\n' + REASONING_END + '\n')
      })
    }
  }
  const offStream = ctx.on('agent/assistant-stream', ({ agent: subject, frame }) => {
    if (subject !== agent) return
    if (frame.type !== 'chunk') {
      closeReasoning()
      return
    }
    const chunk = frame.chunk
    if (chunk === void 0) return
    switch (chunk.type) {
      case 'reasoning-delta':
        if (chunk.text === '') return
        if (!inReasoning) {
          inReasoning = true
          sendIpc({ type: 'reasoning_begin' }, () => {
            io.stdout.write(REASONING_BEGIN + '\n')
          })
        }
        sendIpc({ type: 'reasoning_delta', text: chunk.text }, () => {
          io.stdout.write(chunk.text)
        })
        return
      case 'block-start':
        if (chunk.blockType !== 'reasoning') closeReasoning()
        return
      case 'block-end':
        if (chunk.block === void 0 || chunk.block.type !== 'reasoning') closeReasoning()
        return
      case 'text-delta':
        if (chunk.text === '') return
        streamedText = true
        closeReasoning()
        sendIpc({ type: 'assistant_delta', text: chunk.text }, () => {
          io.stdout.write(chunk.text)
        })
        return
      case 'usage':
        return
      default:
        closeReasoning()
    }
  })
  const tracker = createDelegationTracker(ctx, agent, mode)
  const rootSessionId = String(agent.session.header.id)

  function extractGoalState(session, goalsService, agent) {
    let base = null
    try {
      if (typeof goalsService?.get === 'function' && agent) {
        base = goalsService.get(agent) || null
      }
    } catch {
      /* ignore */
    }
    let startSeq = -1
    let roundCount = 1
    for (let seq = 0; seq < session.seq; seq++) {
      const ev = session.eventAt(SessionSeq(seq))
      if (!ev) continue
      if (ev.type === 'goal/change') {
        const d = ev.data || {}
        if (d.action === 'start') {
          startSeq = seq
          roundCount = 1
          if (!base) {
            base = {
              phase: 'active',
              activation: 'armed',
              goalId: d.goalId,
              title: d.title,
              objective: d.objective,
              verification: d.verification,
              doneWhen: d.doneWhen,
              constraints: d.constraints,
              maxRounds: d.maxRounds
            }
          }
        } else if (base && d.action === 'update') {
          if (d.title !== undefined) base = { ...base, title: d.title }
          if (d.objective !== undefined) base = { ...base, objective: d.objective }
          if (d.verification !== undefined) base = { ...base, verification: d.verification }
          if (d.doneWhen !== undefined) base = { ...base, doneWhen: d.doneWhen }
          if (d.constraints !== undefined) base = { ...base, constraints: d.constraints }
          if (d.maxRounds !== undefined) base = { ...base, maxRounds: d.maxRounds }
        } else if (base && d.action === 'pause') {
          base = { ...base, phase: 'paused', activation: 'idle', summary: d.reason || base.summary }
        } else if (base && d.action === 'resume') {
          base = { ...base, phase: 'active', activation: 'armed' }
        } else if (base && d.action === 'complete') {
          base = {
            ...base,
            phase: 'completed',
            activation: 'idle',
            summary: d.summary || base.summary
          }
        } else if (base && d.action === 'end') {
          base = {
            ...base,
            phase: 'ended',
            activation: 'idle',
            endedReason: d.reason,
            summary: d.summary || base.summary
          }
        }
      } else if (
        startSeq >= 0 &&
        ev.type === 'user/message' &&
        ev.data?.message?.source?.kind === 'plugin' &&
        ev.data?.message?.source?.plugin === 'goal-round-driver'
      ) {
        roundCount += 1
      }
    }
    if (!base) return null
    return {
      ...base,
      round: typeof base.round === 'number' ? base.round : roundCount
    }
  }

  function extractScheduleList(session) {
    if (typeof foldScheduleEvents !== 'function' || typeof scheduleView !== 'function') return []
    try {
      const state = foldScheduleEvents(session.events())
      const nowMs = Date.now()
      const list = []
      for (const record of state.byId.values()) {
        if (record.status === 'pending') {
          list.push(scheduleView(record, nowMs))
        }
      }
      return list
    } catch {
      return []
    }
  }

  /** Emit tool markers for one agent's new events; child cards carry the anchoring delegation call. */
  const flushAgent = (owner) => {
    const session = owner.agent.session
    const tools = owner.pendingTools
    for (; owner.lastSeq < session.seq; owner.lastSeq++) {
      const event = session.eventAt(SessionSeq(owner.lastSeq))
      if (event === void 0) continue
      if (event.type === 'tool/call') {
        const callId = event.data?.callId
        if (typeof callId === 'string' && !tools.has(callId)) {
          const toolName = event.data?.name || 'tool'
          const parentId = owner.anchorId
          tools.set(callId, { name: toolName, parentId })
          tracker.noteToolCall(owner.sessionId, parentId, callId, toolName, event.data?.arguments)
          closeReasoning()
          const toolStartPayload = {
            name: toolName,
            callId,
            ...(parentId ? { parentId } : {}),
            detail: summarizeToolArgs(event.data?.arguments),
            args: clipToolArgs(event.data?.arguments)
          }
          sendIpc({ type: 'tool', state: 'start', payload: toolStartPayload }, () => {
            io.stdout.write('\n' + TOOL_BEGIN + JSON.stringify(toolStartPayload) + '\n')
          })
        }
        continue
      }
      if (event.type === 'tool/result') {
        const callId = event.data?.message?.source?.callId
        if (typeof callId === 'string') {
          // The card must close under the anchor it opened with, even if a later wake re-anchored the child.
          const pending = tools.get(callId)
          tools.delete(callId)
          if (!owner.isRoot && tools.size === 0) {
            owner.activeTool = ''
            owner.activeToolDetail = ''
            owner.updatedAt = Date.now()
          }
          const parentId = pending ? pending.parentId : owner.anchorId
          const resultSteps = extractToolResultSteps(event.data)
          const toolEndPayload = {
            name: pending?.name || 'tool',
            callId,
            ...(parentId ? { parentId } : {}),
            ...(resultSteps ? { steps: resultSteps, detail: resultSteps.join(' · ') } : {})
          }
          sendIpc({ type: 'tool', state: 'done', payload: toolEndPayload }, () => {
            io.stdout.write('\n' + TOOL_END + JSON.stringify(toolEndPayload) + '\n')
          })
        }
        continue
      }
      if (owner.isRoot && event.type === 'todo/write') {
        const todos = Array.isArray(event.data?.todos) ? event.data.todos : []
        closeReasoning()
        sendIpc({ type: 'todo', todos }, () => {
          io.stdout.write('\n' + TODO_BEGIN + JSON.stringify({ todos }) + '\n')
        })
        continue
      }
      if (
        owner.isRoot &&
        (event.type === 'goal/change' ||
          (event.type === 'user/message' &&
            event.data?.message?.source?.kind === 'plugin' &&
            event.data?.message?.source?.plugin === 'goal-round-driver'))
      ) {
        const goal = extractGoalState(session, ctx.get('goals'), owner.agent)
        closeReasoning()
        sendIpc({ type: 'goal', goal }, () => {
          io.stdout.write('\n' + GOAL_BEGIN + JSON.stringify({ goal }) + '\n')
        })
        continue
      }
      if (owner.isRoot && event.type === 'deliverables/presented') {
        const files = Array.isArray(event.data?.files) ? event.data.files : []
        closeReasoning()
        const presentPayload = {
          callId: event.data?.callId || '',
          turn: event.data?.turn ?? 0,
          files
        }
        sendIpc({ type: 'present', ...presentPayload }, () => {
          io.stdout.write('\n' + PRESENT_BEGIN + JSON.stringify(presentPayload) + '\n')
        })
        continue
      }
      if (owner.isRoot && event.type === 'schedule/change') {
        const schedules = extractScheduleList(session)
        closeReasoning()
        sendIpc({ type: 'schedule', schedules }, () => {
          io.stdout.write('\n' + SCHEDULE_BEGIN + JSON.stringify({ schedules }) + '\n')
        })
        continue
      }
      if (owner.isRoot && event.type === 'assistant/message' && event.data?.usage) {
        const usage = event.data.usage
        if (typeof usage.inputTokens === 'number' && usage.inputTokens >= 0) {
          closeReasoning()
          sendIpc({ type: 'context', usage }, () => {
            io.stdout.write('\n' + CONTEXT_BEGIN + JSON.stringify(usage) + '\n')
          })
        }
      }
    }
  }

  const rootEntry = {
    agent,
    sessionId: rootSessionId,
    lastSeq: firstSeq,
    pendingTools: new Map(),
    anchorId: undefined,
    isRoot: true
  }
  const flushSubagentSnapshot = () => {
    if (tracker.children.size === 0) return
    const subagents = tracker.snapshotSubagents()
    const nextJson = JSON.stringify(subagents)
    if (nextJson === lastSubagentJson) return
    lastSubagentJson = nextJson
    closeReasoning()
    sendIpc({ type: 'subagent', subagents }, () => {
      io.stdout.write('\n' + SUBAGENT_BEGIN + JSON.stringify({ subagents }) + '\n')
    })
  }
  const flushEvents = (force = false) => {
    flushAgent(rootEntry)
    for (const child of tracker.children.values()) {
      if (tracker.resolveAnchor(child, force)) flushAgent(child)
    }
    flushSubagentSnapshot()
  }

  const waitTreeIdle = async () => {
    await agent.whenIdle()
    while (
      agent.status === 'running' ||
      Boolean(agent.inbox?.hasPending) ||
      tracker.children.size > 0
    ) {
      if (agent.status === 'running') {
        await agent.whenIdle()
        continue
      }
      if (agent.inbox?.hasPending) {
        await new Promise((resolve) => setTimeout(resolve, 40))
        if (agent.status === 'running') {
          await agent.whenIdle()
          continue
        }
        if (!agent.inbox?.hasPending && !tracker.isBusy()) break
      }
      if (tracker.children.size > 0) {
        if (tracker.isBusy()) {
          await tracker.whenChildrenIdle()
        } else {
          await new Promise((resolve) => setTimeout(resolve, 100))
          if (!tracker.isBusy() && agent.status !== 'running' && !agent.inbox?.hasPending) break
        }
        await agent.whenIdle()
      } else {
        break
      }
    }
  }

  const timer = setInterval(flushEvents, 30)
  try {
    if (opts.autonomousTurn) {
      // Autonomous turn (e.g. schedule reminder already queued on agent)
      await waitTreeIdle()
    } else {
      const trimmedTask = task.trim()
      const slashMatch = /^\/(compact|goal|feedback)(?=$|\s)/i.exec(trimmedTask)
      const commands = ctx.get('commands')
      if (slashMatch && typeof commands?.execute === 'function') {
        const settled = await commands.execute(agent, trimmedTask, [])
        if (settled?.status === 'Complete' && settled.result?.text) {
          streamedText = true
          closeReasoning()
          const cmdText = settled.result.text + '\n'
          sendIpc({ type: 'assistant_delta', text: cmdText }, () => {
            io.stdout.write(cmdText)
          })
        } else if (settled?.status === 'Failed') {
          const errMsg =
            settled.error instanceof Error ? settled.error.message : String(settled.error)
          throw new Error(errMsg)
        }
      } else {
        const fullTask = modePreamble(mode) + task
        const userContent = await buildUserContent(fullTask, ctx.get('attachments'), io)
        agent.followup(
          createUserMessage({
            content: userContent,
            source: { kind: 'user' }
          })
        )
      }
      await waitTreeIdle()
    }

    // Multi-round Goal Driver: if a goal is active & armed, goal-round-driver
    // checkpoints the session after turn/end and queues the next round.
    const goalsService = ctx.get('goals')
    while (typeof goalsService?.get === 'function') {
      const g = goalsService.get(agent)
      if (!g || g.phase !== 'active' || g.activation !== 'armed') break
      let restarted = false
      for (let i = 0; i < 50; i++) {
        await new Promise((resolve) => setTimeout(resolve, 50))
        if (agent.status === 'running' || tracker.isBusy()) {
          restarted = true
          break
        }
        const cur = goalsService.get(agent)
        if (!cur || cur.phase !== 'active' || cur.activation !== 'armed') break
      }
      if (!restarted && agent.status !== 'running' && !tracker.isBusy()) break
      await waitTreeIdle()
    }
  } finally {
    clearInterval(timer)
    offStream()
    tracker.dispose()
  }
  flushEvents(true)
  if (inReasoning) {
    closeReasoning()
  }
  try {
    await sessions.flush(agent.session)
  } catch (error) {
    io.stderr.write(
      '[aiart-runner] session flush failed: ' +
        (error instanceof Error ? error.message : String(error)) +
        '\n'
    )
  }
  const outcome = summarize(agent.session, firstSeq)
  if (!streamedText && outcome.text) {
    sendIpc({ type: 'assistant_delta', text: outcome.text + '\n' }, () => {
      io.stdout.write(outcome.text + '\n')
    })
  }
  if (outcome.reason?.kind === 'error') {
    io.stderr.write(
      'dsh: ' + outcome.reason.error.code + ': ' + outcome.reason.error.message + '\n'
    )
    throw new Error(outcome.reason.error.message || outcome.reason.error.code || 'turn error')
  }
  return outcome
}

async function runPersistent(ctx, io) {
  let currentMode = (process.env.AIART_MODE || 'craft').trim() || 'craft'
  let currentRunId = process.env.AIART_RUN_ID || 'run'
  let forcedSelection = null
  const agentSlot = { handle: undefined, sessionId: '', model: '', provider: '' }
  let turnBusy = false
  let turnQueue = Promise.resolve()

  const answerAskUserQuestion = registerAskUserTool(
    ctx,
    io,
    () => currentMode,
    () => currentRunId
  )
  registerDelegationGuard(ctx, () => currentMode)
  registerDsmlStreamTranspiler(ctx, () => currentMode)

  await ctx.get('loader')?.await()
  const defaultModel = ctx.get('agentDefaultModel')
  const agents = ctx.get('agents')
  const sessions = ctx.get('sessions')
  if (agents === void 0 || defaultModel === void 0 || sessions === void 0) {
    throw new Error('required services missing')
  }

  const onAutonomousWake = (agent) => {
    if (turnBusy || !agentSlot.handle || agentSlot.handle.agent !== agent) return
    turnBusy = true
    const schedRunId = 'sched-' + Date.now()
    currentRunId = schedRunId
    const selection = forcedSelection || defaultModel.currentSelection()
    const schedStartPayload = {
      runId: schedRunId,
      sessionId: agentSlot.sessionId,
      mode: currentMode,
      model: selection?.model || ''
    }
    sendIpc({ type: 'schedule_turn_start', ...schedStartPayload }, () => {
      io.stderr.write(
        '[aiart-runner] schedule_turn_start ' + JSON.stringify(schedStartPayload) + '\n'
      )
    })
    const schedules = extractScheduleList(agent.session)
    sendIpc({ type: 'schedule', schedules }, () => {
      io.stdout.write('\n' + SCHEDULE_BEGIN + JSON.stringify({ schedules }) + '\n')
    })
    turnQueue = turnQueue
      .then(async () => {
        try {
          await runOneTurn(ctx, io, {
            task: '',
            autonomousTurn: true,
            sessionId: agentSlot.sessionId,
            mode: currentMode,
            runId: schedRunId,
            selection,
            answerAskUserQuestion,
            agentSlot
          })
          sendIpc({ type: 'turn_done', ok: true }, () => {
            io.stderr.write('[aiart-runner] turn_done ' + JSON.stringify({ ok: true }) + '\n')
          })
        } catch (error) {
          const errText = error instanceof Error ? error.message : String(error)
          sendIpc({ type: 'turn_done', ok: false, error: errText }, () => {
            io.stderr.write(
              '[aiart-runner] turn_done ' + JSON.stringify({ ok: false, error: errText }) + '\n'
            )
          })
        } finally {
          turnBusy = false
        }
      })
      .catch(() => {
        turnBusy = false
      })
  }
  ctx.on('agent/turn-start', ({ agent }) => onAutonomousWake(agent))
  ctx.on('agent/status', ({ agent, status }) => {
    if (status === 'running') onAutonomousWake(agent)
  })

  sendIpc({ type: 'ready' }, () => {
    io.stderr.write('[aiart-runner] ready\n')
  })

  const enqueueOp = (fn) => {
    turnQueue = turnQueue.then(fn).catch((err) => {
      io.stderr.write(
        '[aiart-runner] queue error: ' + (err instanceof Error ? err.message : String(err)) + '\n'
      )
    })
  }

  const rl = createInterface({ input: process.stdin, crlfDelay: Infinity })

  const handleCommand = (msg) => {
    const op = msg?.op
    if (op === 'shutdown') {
      const liveAgent = agentSlot.handle?.agent
      try {
        if (liveAgent && typeof liveAgent.cancel === 'function') {
          liveAgent.cancel({ kind: 'disposed' })
        }
      } catch {
        /* ignore */
      }
      releaseAgentSlot(agentSlot).finally(() => {
        rl.close()
        io.exit(0)
      })
      return
    }
    if (op === 'steer') {
      const text = typeof msg.text === 'string' ? msg.text.trim() : ''
      const subagentSessionId =
        typeof msg.subagentSessionId === 'string' ? msg.subagentSessionId.trim() : ''
      let targetAgent = agentSlot.handle?.agent
      if (subagentSessionId && typeof agents?.get === 'function') {
        try {
          targetAgent = agents.get(SessionId(subagentSessionId)) || targetAgent
        } catch {
          /* ignore */
        }
      }
      if (targetAgent && text) {
        void (async () => {
          try {
            const steerPrompt =
              '[Live User Steering — apply immediately from the next step]\n' + text
            const userContent = await buildUserContent(steerPrompt, ctx.get('attachments'), io)
            const userMsg = createUserMessage({
              content: userContent,
              source: { kind: 'user' }
            })
            if (targetAgent.status === 'running' && typeof targetAgent.inject === 'function') {
              targetAgent.inject(userMsg)
            } else if (typeof targetAgent.followup === 'function') {
              targetAgent.followup(userMsg)
            } else if (typeof targetAgent.inject === 'function') {
              targetAgent.inject(userMsg)
            }
            const steerPayload = {
              text,
              targetSessionId: subagentSessionId || agentSlot.sessionId
            }
            sendIpc({ type: 'steered', ...steerPayload }, () => {
              io.stdout.write('\n' + STEER_BEGIN + JSON.stringify(steerPayload) + '\n')
            })
          } catch (error) {
            io.stderr.write(
              '[aiart-runner] steer error: ' +
                (error instanceof Error ? error.message : String(error)) +
                '\n'
            )
          }
        })()
      }
      return
    }
    if (op === 'goal_control') {
      const action = typeof msg.action === 'string' ? msg.action : ''
      const summary = typeof msg.summary === 'string' ? msg.summary : undefined
      const liveAgent = agentSlot.handle?.agent
      const goals = ctx.get('goals')
      if (action === 'resume' && !turnBusy) {
        enqueueOp(async () => {
          turnBusy = true
          try {
            const selection = forcedSelection || defaultModel.currentSelection()
            await runOneTurn(ctx, io, {
              task: '/goal resume',
              sessionId: typeof msg.sessionId === 'string' ? msg.sessionId : agentSlot.sessionId,
              mode: currentMode,
              runId: currentRunId,
              selection,
              answerAskUserQuestion,
              agentSlot
            })
            sendIpc({ type: 'turn_done', ok: true }, () => {
              io.stderr.write('[aiart-runner] turn_done ' + JSON.stringify({ ok: true }) + '\n')
            })
          } catch (error) {
            const errText = error instanceof Error ? error.message : String(error)
            sendIpc({ type: 'turn_done', ok: false, error: errText }, () => {
              io.stderr.write(
                '[aiart-runner] turn_done ' + JSON.stringify({ ok: false, error: errText }) + '\n'
              )
            })
          } finally {
            turnBusy = false
          }
        })
        return
      }
      if (liveAgent && goals) {
        try {
          if (action === 'pause') {
            goals.pause?.(liveAgent, summary || 'Paused by user')
            if (liveAgent.status === 'running') liveAgent.cancel?.({ kind: 'user' })
          } else if (action === 'end') {
            goals.end?.(liveAgent, 'user', summary || 'Ended by user')
            if (liveAgent.status === 'running') liveAgent.cancel?.({ kind: 'user' })
          }
          const goal = extractGoalState(liveAgent.session, goals, liveAgent)
          sendIpc({ type: 'goal', goal }, () => {
            io.stdout.write('\n' + GOAL_BEGIN + JSON.stringify({ goal }) + '\n')
          })
          io.stderr.write(
            '[aiart-runner] goal_control_ack ' + JSON.stringify({ ok: true, goal }) + '\n'
          )
        } catch (error) {
          io.stderr.write(
            '[aiart-runner] goal_control_ack ' +
              JSON.stringify({
                ok: false,
                error: error instanceof Error ? error.message : String(error)
              }) +
              '\n'
          )
        }
      } else {
        io.stderr.write(
          '[aiart-runner] goal_control_ack ' +
            JSON.stringify({ ok: false, error: 'no active agent' }) +
            '\n'
        )
      }
      return
    }
    if (op === 'schedule_delete') {
      const scheduleId = typeof msg.scheduleId === 'string' ? msg.scheduleId.trim() : ''
      const liveAgent = agentSlot.handle?.agent
      if (liveAgent && scheduleId) {
        try {
          liveAgent.session.append('schedule/change', {
            action: 'delete',
            id: scheduleId,
            reason: 'cancelled'
          })
          sessions.flush(liveAgent.session).catch(() => {})
          const schedules = extractScheduleList(liveAgent.session)
          sendIpc({ type: 'schedule', schedules }, () => {
            io.stdout.write('\n' + SCHEDULE_BEGIN + JSON.stringify({ schedules }) + '\n')
          })
          io.stderr.write(
            '[aiart-runner] schedule_delete_ack ' + JSON.stringify({ ok: true, schedules }) + '\n'
          )
        } catch (error) {
          io.stderr.write(
            '[aiart-runner] schedule_delete_ack ' +
              JSON.stringify({
                ok: false,
                error: error instanceof Error ? error.message : String(error)
              }) +
              '\n'
          )
        }
      } else {
        io.stderr.write(
          '[aiart-runner] schedule_delete_ack ' +
            JSON.stringify({ ok: false, error: 'no active agent or scheduleId' }) +
            '\n'
        )
      }
      return
    }
    if (op === 'release_session') {
      const targetSessionId = typeof msg.sessionId === 'string' ? msg.sessionId.trim() : ''
      enqueueOp(async () => {
        if (
          agentSlot.handle?.agent &&
          (!targetSessionId || agentSlot.sessionId === targetSessionId)
        ) {
          try {
            await sessions.flush(agentSlot.handle.agent.session)
          } catch {
            /* ignore */
          }
          await releaseAgentSlot(agentSlot)
        }
        sendIpc({ type: 'session_released', sessionId: targetSessionId }, () => {
          io.stderr.write(
            '[aiart-runner] session_released ' +
              JSON.stringify({ ok: true, sessionId: targetSessionId }) +
              '\n'
          )
        })
      })
      return
    }
    if (op === 'set_model') {
      enqueueOp(async () => {
        const modelId = typeof msg.modelId === 'string' ? msg.modelId.trim() : ''
        if (!modelId) {
          io.stderr.write(
            '[aiart-runner] model_set ' +
              JSON.stringify({ ok: false, error: 'missing modelId' }) +
              '\n'
          )
          return
        }
        const cur = defaultModel.currentSelection()
        forcedSelection = {
          provider: cur?.provider || 'deepseek-official',
          model: modelId
        }
        // Must dispose so the session write lease is released before next resume
        await releaseAgentSlot(agentSlot)
        io.stderr.write('[aiart-runner] model_set ' + JSON.stringify({ ok: true, modelId }) + '\n')
      })
      return
    }
    if (op === 'prompt') {
      enqueueOp(async () => {
        const task = typeof msg.task === 'string' ? msg.task : ''
        if (!task.trim()) {
          sendIpc({ type: 'turn_done', ok: false, error: 'empty task' }, () => {
            io.stderr.write(
              '[aiart-runner] turn_done ' +
                JSON.stringify({ ok: false, error: 'empty task' }) +
                '\n'
            )
          })
          return
        }
        turnBusy = true
        currentMode = typeof msg.mode === 'string' && msg.mode ? msg.mode : currentMode
        currentRunId = typeof msg.runId === 'string' && msg.runId ? msg.runId : currentRunId
        const selection = forcedSelection || defaultModel.currentSelection()
        const promptStartPayload = {
          runId: currentRunId,
          mode: currentMode,
          model: selection?.model || ''
        }
        sendIpc({ type: 'prompt_start', ...promptStartPayload }, () => {
          io.stderr.write(
            '[aiart-runner] prompt_start ' + JSON.stringify(promptStartPayload) + '\n'
          )
        })
        try {
          await runOneTurn(ctx, io, {
            task,
            sessionId: typeof msg.sessionId === 'string' ? msg.sessionId : '',
            mode: currentMode,
            runId: currentRunId,
            selection,
            answerAskUserQuestion,
            agentSlot
          })
          sendIpc({ type: 'turn_done', ok: true }, () => {
            io.stderr.write('[aiart-runner] turn_done ' + JSON.stringify({ ok: true }) + '\n')
          })
        } catch (error) {
          const errText = error instanceof Error ? error.message : String(error)
          sendIpc({ type: 'turn_done', ok: false, error: errText }, () => {
            io.stderr.write(
              '[aiart-runner] turn_done ' + JSON.stringify({ ok: false, error: errText }) + '\n'
            )
          })
        } finally {
          turnBusy = false
        }
      })
      return
    }
    io.stderr.write('[aiart-runner] unknown op: ' + String(op) + '\n')
  }

  if (typeof process.on === 'function') {
    process.on('message', (msg) => {
      if (msg && typeof msg === 'object' && typeof msg.op === 'string') {
        handleCommand(msg)
      }
    })
  }

  rl.on('line', (line) => {
    const trimmed = line.trim()
    if (!trimmed) return
    let msg
    try {
      msg = JSON.parse(trimmed)
    } catch {
      io.stderr.write('[aiart-runner] ignore non-json stdin line\n')
      return
    }
    handleCommand(msg)
  })
  await new Promise((resolve) => rl.once('close', resolve))
  await releaseAgentSlot(agentSlot)
  io.exit(0)
}

/** One-shot path (npx / legacy): single task then exit */
async function runOnce(ctx, task, io) {
  const mode = (process.env.AIART_MODE || 'craft').trim() || 'craft'
  const runId = process.env.AIART_RUN_ID || 'run'
  // Ask：不注册 ask_user_question（与历史 one-shot 行为一致）
  const answerAskUserQuestion =
    mode === 'ask'
      ? async () => ({ answers: [] })
      : registerAskUserTool(
          ctx,
          io,
          () => mode,
          () => runId
        )
  registerDelegationGuard(ctx, () => mode)
  registerDsmlStreamTranspiler(ctx, () => mode)
  await ctx.get('loader')?.await()
  const defaultModel = ctx.get('agentDefaultModel')
  if (defaultModel === void 0) return
  const agentSlot = { handle: undefined, sessionId: '', model: '', provider: '' }
  const selection = defaultModel.currentSelection()
  const outcome = await runOneTurn(ctx, io, {
    task,
    sessionId: (process.env.AIART_SESSION_ID || '').trim(),
    mode,
    runId,
    selection,
    answerAskUserQuestion,
    agentSlot
  })
  await releaseAgentSlot(agentSlot)
  io.exit(outcome.reason?.kind === 'completed' ? 0 : 1)
}

function apply(ctx, config) {
  const exit = ctx.get('appExit')
  if (exit === void 0) {
    throw new Error(
      'aiart-headless-runner: the launcher must provide ctx.appExit before the tree mounts'
    )
  }
  const io = { stdout: process.stdout, stderr: process.stderr, exit }
  const task = config.task
  const persistent = process.env.AIART_PERSISTENT === '1' || task === PERSISTENT_TASK || task === ''
  const run = persistent ? runPersistent(ctx, io) : runOnce(ctx, task, io)
  run.catch((error) => {
    io.stderr.write('dsh: ' + (error instanceof Error ? error.message : String(error)) + '\n')
    io.exit(1)
  })
}

